function pairs(n) {
  return n > 1 ? n * (n - 1) / 2 : 0;
}

function rankPairwise(items, judgements) {
  var known = {};
  items.forEach(function (x) { known['#' + x] = true; });
  var last = {};
  judgements.forEach(function (j) {
    var w = j[0], l = j[1];
    if (!known['#' + w] || !known['#' + l] || w === l) return;
    var key = [w, l].sort().join('\u0000');
    last[key] = w;
  });
  var wins = {};
  items.forEach(function (x) { wins['#' + x] = 0; });
  Object.keys(last).forEach(function (k) { wins['#' + last[k]]++; });
  return items
    .map(function (x, i) { return { x: x, i: i, w: wins['#' + x] }; })
    .sort(function (a, b) { return b.w - a.w || a.i - b.i; })
    .map(function (o) { return o.x; });
}
